<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { TagContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: TagContract  = $props();
let expanded=$state(false);let root=$state<HTMLDivElement>();let active=$state(untrack(()=>p.items.find(x=>!x.disabled)?.id));function targets(){return [...root!.querySelectorAll<HTMLElement>('[data-tag-action]')].filter(x=>!x.matches(':disabled'));}function key(e:KeyboardEvent){if(ignoredKey(e)||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const list=targets(),i=list.indexOf(document.activeElement as HTMLElement),next=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;active=list[next]?.dataset.tagAction;list[next]?.focus();}async function remove(id:string){const index=p.items.findIndex(x=>x.id===id);p.onRemove?.({id});await tick();if(p.items.some(x=>x.id===id))return;const next=p.items.slice(0,index).reverse().find(x=>!x.disabled)??p.items.find(x=>!x.disabled);active=next?.id;(targets().find(x=>x.dataset.tagAction===next?.id)??root)?.focus();}async function add(id:string){p.onAdd?.({id});await tick();document.getElementById(p.appliedBarId??'')?.focus();}function select(id:string){const ids=p.selectedIds??[];p.onSelectionChange?.({ids:ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]});}
$effect.pre(()=>{const enabled=p.items.filter(item=>!item.disabled);if(enabled.some(item=>item.id===active))return;const ownedFocus=root?.contains(document.activeElement)??false;active=enabled[0]?.id;if(ownedFocus)void tick().then(()=>{(targets().find(node=>node.dataset.tagAction===active)??root)?.focus();});});
</script>
<div bind:this={root} role="group" aria-label="태그" tabindex="-1" onkeydown={key} {...owned('tag','root',expanded&&'expanded')}><ul {...owned('tag','list',expanded&&'expanded')}>{#each p.items as item(item.id)}<li {...owned('tag','item',p.selectedIds?.includes(item.id)&&'selected',item.disabled&&'disabled')}>{#if p.mode==='link'&&item.href}<a href={item.href}>{item.label}</a>{:else if p.mode==='toggle'}<button type="button" aria-pressed={p.selectedIds?.includes(item.id)??false} data-tag-action={item.id} tabindex={active===item.id?0:-1} disabled={item.disabled} onclick={()=>select(item.id)}>{item.label}</button>{:else if p.mode==='add-filter'}<button type="button" disabled={item.disabled} aria-label={`${item.label} 필터 옵션 추가`} onclick={()=>add(item.id)}>{item.label}</button>{:else}<span>{item.label}</span>{#if p.mode==='removable'}<button type="button" aria-label={`${item.label} 옵션 삭제`} data-tag-action={item.id} tabindex={active===item.id?0:-1} disabled={item.disabled} {...owned('tag','remove',item.disabled&&'disabled')} onclick={()=>remove(item.id)}>×</button>{/if}{/if}</li>{/each}</ul>{#if p.mode==='removable'&&p.items.length}<button type="button" {...owned('tag','clear')} onclick={()=>p.onClear?.()}>전체 삭제</button>{/if}{#if p.items.length>5}<button type="button" {...owned('tag','more',expanded&&'expanded')} aria-expanded={expanded} onclick={()=>expanded=!expanded}>{expanded?'접기':'더 보기'}</button>{/if}</div>
